/**
 * Adds two finite numbers and returns their sum.
 *
 * Supports positive numbers, negative numbers, and zero.
 * Rejects non-number arguments and non-finite numbers (NaN, Infinity, -Infinity).
 *
 * @param {number} a - The first addend (must be a finite number).
 * @param {number} b - The second addend (must be a finite number).
 * @returns {number} The arithmetic sum of a and b.
 * @throws {TypeError} If either argument is not of type number.
 * @throws {RangeError} If either argument is not a finite number.
 */
function add(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number') {
    throw new TypeError('add() expects two number arguments');
  }
  if (!Number.isFinite(a) || !Number.isFinite(b)) {
    throw new RangeError('add() expects two finite numbers');
  }
  return a + b;
}

module.exports = { add };
